// Define the node structure
struct Node {
    int data;
    struct Node* next;
};

// Insert a new node at the beginning — O(1)
struct Node* insertAtBeginning(struct Node* head, int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = head;  // point new node to old head
    return newNode;        // new node becomes new head
}

// Traverse and print the list — O(n)
void traverse(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        printf("%d -> ", current->data);
        current = current->next;
    }
    printf("NULL\n");
}

int main() {
    struct Node* head = NULL;  // empty list

    head = insertAtBeginning(head, 30);
    head = insertAtBeginning(head, 20);
    head = insertAtBeginning(head, 10);

    // Output: 10 -> 20 -> 30 -> NULL
    traverse(head);
    return 0;
}

// Delete the first node with the given key — O(n)
struct Node* deleteNode(struct Node* head, int key) {
    struct Node *current = head, *prev = NULL;

    // Case 1: key is in the head node
    if (current != NULL && current->data == key) {
        struct Node* temp = current;
        head = current->next;  // move head to next node
        free(temp);            // free the old head
        return head;
    }

    // Case 2: search for the key, keeping track of prev
    while (current != NULL && current->data != key) {
        prev = current;
        current = current->next;
    }

    // Key not found
    if (current == NULL) return head;

    // Unlink the node
    prev->next = current->next;
    free(current);
    return head;
}

#include <stdio.h>
#define MAX 100

int stack[MAX];
int top = -1;  // empty stack

void push(int value) {
    if (top == MAX - 1) {
        printf("Stack Overflow!\n");
        return;
    }
    stack[++top] = value;  // increment top, then insert
    printf("Pushed %d\n", value);
}

int pop() {
    if (top == -1) {
        printf("Stack Underflow!\n");
        return -1;
    }
    return stack[top--];  // return current top, then decrement
}

int peek() {
    if (top == -1) return -1;
    return stack[top];
}

int main() {
    push(10);  // stack: [10]
    push(20);  // stack: [10, 20]
    push(30);  // stack: [10, 20, 30]
    printf("Top: %d\n", peek());     // Output: 30
    printf("Popped: %d\n", pop());   // Output: 30, stack: [10, 20]
    printf("Popped: %d\n", pop());   // Output: 20, stack: [10]
    return 0;
}

// Check if parentheses are balanced: (), {}, []
#include <stdbool.h>
#include <string.h>

bool isBalanced(char* expr) {
    char stack[100];
    int top = -1;

    for (int i = 0; expr[i] != '\0'; i++) {
        char ch = expr[i];

        // Push opening brackets
        if (ch == '(' || ch == '{' || ch == '[') {
            stack[++top] = ch;
        }
        // Check closing brackets
        else if (ch == ')' || ch == '}' || ch == ']') {
            if (top == -1) return false;  // nothing to match

            char open = stack[top--];
            if ((ch == ')' && open != '(') ||
                (ch == '}' && open != '{') ||
                (ch == ']' && open != '[')) {
                return false;  // mismatch
            }
        }
    }
    return top == -1;  // balanced if stack is empty
}

