// Binary Search — O(log n). Array MUST be sorted.
int binarySearch(int arr[], int n, int key) {
    int low = 0, high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (arr[mid] == key) {
            return mid;        // found
        } else if (arr[mid] < key) {
            low = mid + 1;     // search right half
        } else {
            high = mid - 1;    // search left half
        }
    }
    return -1;  // not found
}

// Bubble Sort — O(n²) worst, O(n) best (with optimization)
void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int swapped = 0;  // optimization: stop if no swaps

        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap adjacent elements
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = 1;
            }
        }

        // If no swaps in this pass, array is sorted
        if (!swapped) break;  // O(n) best case
    }
}

// Selection Sort — always O(n²), but minimal swaps (O(n))
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;

        // Find the minimum in the unsorted portion [i..n-1]
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }

        // Swap the minimum with the first unsorted element
        if (minIndex != i) {
            int temp = arr[i];
            arr[i] = arr[minIndex];
            arr[minIndex] = temp;
        }
        // Only 1 swap per pass — total n-1 swaps
    }
}

// Insertion Sort — O(n²) worst, O(n) best
void insertionSort(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i];  // the element to insert
        int j = i - 1;

        // Shift elements > key one position right
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }

        // Insert key at its correct position
        arr[j + 1] = key;
    }
}

#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *left, *right;
};

// Create a new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Insert into BST — O(log n) average, O(n) worst
struct Node* insert(struct Node* root, int value) {
    if (root == NULL) return createNode(value);

    if (value < root->data)
        root->left = insert(root->left, value);    // go left
    else if (value > root->data)
        root->right = insert(root->right, value);  // go right
    // if equal, do nothing (no duplicates)

    return root;
}

// Inorder traversal — produces sorted output
void inorder(struct Node* root) {
    if (root != NULL) {
        inorder(root->left);      // visit left subtree
        printf("%d ", root->data); // visit root
        inorder(root->right);     // visit right subtree
    }
}

int main() {
    struct Node* root = NULL;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 70);
    insert(root, 20);
    insert(root, 40);
    insert(root, 60);
    insert(root, 80);

    // Output: 20 30 40 50 60 70 80
    inorder(root);
    return 0;
}
